//! Manager regressions for actual canonical Render outputs and production path policy.
use std::{fs,path::{Path,PathBuf},sync::atomic::{AtomicUsize,Ordering}};
use workbench_host::{session,scene_plan::handoff::CutId,workflow::{import,render_jobs,state::{ProjectState,JobRecord,JobScope,JobStatus,STATE_REL}}};
const OUT:&str="Scenes/Scene1/Cut1/S01C01.mp4";
fn read(root:&Path)->ProjectState{ProjectState::from_json(&fs::read_to_string(root.join(STATE_REL)).unwrap()).unwrap()}
fn fixture()->(tempfile::TempDir,PathBuf){session::close();let t=tempfile::tempdir().unwrap();let root=t.path().join("project");fs::create_dir_all(root.join("Scenes/Scene1/Cut1")).unwrap();fs::create_dir_all(root.join("Scenes/Scene1/Cut2")).unwrap();let mut s=ProjectState::new();let scene=s.scene_mut(1,"Scene one");for n in [1,2]{let cut=scene.cut_mut(n);cut.stable_id=format!("shot-{n}");}scene.cuts[0].selected_take=Some("retained-selected-take".into());for n in [1,2]{let mut j=JobRecord::open(format!("render-{n}"),"render");j.output_path=Some(format!("Scenes/Scene1/Cut{n}/S01C0{n}.mp4"));j.scope=Some(JobScope{kind:"shot".into(),id:format!("shot-{n}")});j.raw_provider_id=Some(CutId::new(1,n).code());s.jobs.push(j);}import::persist_state(&root,&s).unwrap();session::open(root.to_str().unwrap()).unwrap();(t,root)}
fn save(root:&Path,s:&ProjectState){import::persist_state(root,s).unwrap();}
#[test]
fn canonical_lifecycle_and_boundary_cases(){
 // Real dispatch observation and file-backed success, preserving all other scene/media state.
 let (_t,root)=fixture();let before=read(&root);let result=render_jobs::with_render_job(&root,OUT,||{let mid=read(&root);assert_eq!(mid.jobs[0].status,JobStatus::Running);assert_eq!(mid.jobs[1],before.jobs[1]);assert_eq!(serde_json::to_value(&mid.scenes).unwrap(),serde_json::to_value(&before.scenes).unwrap());fs::write(root.join(OUT),b"local-output-bytes").unwrap();Ok("saved local output".into())}).unwrap();assert_eq!(result,"saved local output");let done=read(&root);assert_eq!(done.jobs[0].status,JobStatus::Completed);assert!(done.jobs[0].started_at.is_some()&&done.jobs[0].completed_at.is_some());assert_eq!(done.jobs[0].attempts[0].status,JobStatus::Completed);assert_eq!(done.jobs[1],before.jobs[1]);assert_eq!(serde_json::to_value(&done.scenes).unwrap(),serde_json::to_value(&before.scenes).unwrap());assert_eq!(fs::read(root.join(OUT)).unwrap(),b"local-output-bytes");
 // Complete error propagation, no fabricated asset, no selected-media changes.
 let (_t,root)=fixture();let before=read(&root);let error="provider-failed: exact terminal fixture";assert_eq!(render_jobs::with_render_job(&root,OUT,||{assert_eq!(read(&root).jobs[0].status,JobStatus::Running);Err(error.into())}).unwrap_err(),error);let failed=read(&root);assert_eq!(failed.jobs[0].status,JobStatus::Failed);assert_eq!(failed.jobs[0].error.as_deref(),Some(error));assert!(failed.jobs[0].completed_at.is_some());assert!(!root.join(OUT).exists());assert_eq!(serde_json::to_value(&failed.scenes).unwrap(),serde_json::to_value(&before.scenes).unwrap());assert_eq!(failed.jobs[1],before.jobs[1]);
 // Accepted remote request without delivered bytes is NOT a completed render.
 let (_t,root)=fixture();render_jobs::with_render_job(&root,OUT,||Ok("accepted; awaiting output".into())).unwrap();let pending=read(&root);assert_eq!(pending.jobs[0].status,JobStatus::Running);assert!(pending.jobs[0].completed_at.is_none());assert!(pending.jobs[0].output_asset_ids.is_empty());
 // Duplicate prepared output must fail before dispatch, unchanged state.
 let (_t,root)=fixture();let mut s=read(&root);let mut duplicate=s.jobs[0].clone();duplicate.id="duplicate".into();s.jobs.push(duplicate);save(&root,&s);let before=fs::read(root.join(STATE_REL)).unwrap();let calls=AtomicUsize::new(0);assert!(render_jobs::with_render_job(&root,OUT,||{calls.fetch_add(1,Ordering::SeqCst);Ok("MUST NOT DISPATCH".into())}).is_err());assert_eq!(calls.load(Ordering::SeqCst),0);assert_eq!(fs::read(root.join(STATE_REL)).unwrap(),before);
 // Exact saved output with wrong shot bucket cannot become generic media fallback.
 let (_t,root)=fixture();let mut s=read(&root);s.jobs.truncate(1);s.jobs[0].output_path=Some("Scenes/Scene1/Cut2/wrong.mp4".into());save(&root,&s);let before=fs::read(root.join(STATE_REL)).unwrap();assert!(render_jobs::with_render_job(&root,"Scenes/Scene1/Cut2/wrong.mp4",||panic!("wrong bucket dispatched")).is_err());assert_eq!(fs::read(root.join(STATE_REL)).unwrap(),before);
 // A saved path redirected into another scene must be refused, not silently treated as no match.
 let (_t,root)=fixture();fs::create_dir_all(root.join("Scenes/Scene2/Cut1")).unwrap();fs::remove_dir(root.join("Scenes/Scene1/Cut1")).unwrap();std::os::unix::fs::symlink(root.join("Scenes/Scene2/Cut1"),root.join("Scenes/Scene1/Cut1")).unwrap();let before=fs::read(root.join(STATE_REL)).unwrap();let calls=AtomicUsize::new(0);assert!(render_jobs::with_render_job(&root,OUT,||{calls.fetch_add(1,Ordering::SeqCst);Ok("MUST NOT DISPATCH".into())}).is_err());assert_eq!(calls.load(Ordering::SeqCst),0);assert!(!root.join("Scenes/Scene2/Cut1/S01C01.mp4").exists());assert_eq!(fs::read(root.join(STATE_REL)).unwrap(),before);
 // Canonical root aliases preserve exact binding.
 let (_t,root)=fixture();let alias=root.join("../project");render_jobs::with_render_job(&alias,OUT,||{assert_eq!(read(&root).jobs[0].status,JobStatus::Running);fs::write(root.join(OUT),b"alias-output").unwrap();Ok("alias done".into())}).unwrap();assert_eq!(read(&root).jobs[0].status,JobStatus::Completed);
 // A file appearing after preparation is not attributable to this operation.
 let (_t,root)=fixture();fs::write(root.join(OUT),b"preexisting-unowned-output").unwrap();let before=fs::read(root.join(STATE_REL)).unwrap();let calls=AtomicUsize::new(0);assert!(render_jobs::with_render_job(&root,OUT,||{calls.fetch_add(1,Ordering::SeqCst);Ok("accepted without delivery".into())}).is_err());assert_eq!(calls.load(Ordering::SeqCst),0);assert_eq!(fs::read(root.join(OUT)).unwrap(),b"preexisting-unowned-output");assert_eq!(fs::read(root.join(STATE_REL)).unwrap(),before);
 // A second exact destination cannot fall through to generic dispatch after the first starts/settles.
 for status in [JobStatus::Running,JobStatus::Completed,JobStatus::Failed]{let (_t,root)=fixture();let mut s=read(&root);s.jobs[0].status=status;save(&root,&s);let before=fs::read(root.join(STATE_REL)).unwrap();let calls=AtomicUsize::new(0);assert!(render_jobs::with_render_job(&root,OUT,||{calls.fetch_add(1,Ordering::SeqCst);Ok("changed request same destination".into())}).is_err());assert_eq!(calls.load(Ordering::SeqCst),0);assert_eq!(fs::read(root.join(STATE_REL)).unwrap(),before);}
 // The first in-flight closure observes the same duplicate-destination refusal.
 let (_t,root)=fixture();render_jobs::with_render_job(&root,OUT,||{assert!(render_jobs::with_render_job(&root,OUT,||panic!("second destination dispatched")).is_err());fs::write(root.join(OUT),b"first-only").unwrap();Ok("first done".into())}).unwrap();assert_eq!(fs::read(root.join(OUT)).unwrap(),b"first-only");
 // Normal generic media is supported without inventing a prepared render.
 let (_t,root)=fixture();fs::create_dir(root.join("Renders")).unwrap();let before=fs::read(root.join(STATE_REL)).unwrap();assert_eq!(render_jobs::with_render_job(&root,"Renders/generic.mp4",||Ok("generic".into())).unwrap(),"generic");assert_eq!(fs::read(root.join(STATE_REL)).unwrap(),before);
 // The current open root remains authoritative even for a direct production helper call.
 let (t,root)=fixture();let outside=t.path().join("outside");fs::create_dir_all(outside.join("Preproduction")).unwrap();fs::create_dir_all(outside.join("Scenes/Scene1/Cut1")).unwrap();let before=fs::read(root.join(STATE_REL)).unwrap();fs::write(outside.join(STATE_REL),&before).unwrap();let calls=AtomicUsize::new(0);assert!(render_jobs::with_render_job(&outside,OUT,||{calls.fetch_add(1,Ordering::SeqCst);Ok("MUST NOT DISPATCH".into())}).is_err());assert_eq!(calls.load(Ordering::SeqCst),0);assert_eq!(fs::read(outside.join(STATE_REL)).unwrap(),before);
 session::close();
}
